import type { FilterValue } from 'models/Filters';
import {
  getClosedMonthIndex,
  getClosedYear,
  isCanonicalMonthStartDate,
  normalizeTimePeriodDtEnd,
  normalizeTimePeriodType,
  TimePeriodType,
} from 'utils/timePeriod/timePeriodAvailability';

const CALENDAR_MONTH_COUNT = 12;

interface LineChartDatasetShape {
  data?: readonly unknown[];
}

interface DeriveTimePeriodHighlightedIndexesParams {
  periodType: FilterValue | undefined;
  dtEnd: FilterValue | undefined;
  cutoffDate?: string;
  labels?: readonly string[];
  datasets?: readonly LineChartDatasetShape[];
}

const hasFixedCalendarYearShape = (
  labels?: readonly string[],
  datasets?: readonly LineChartDatasetShape[],
): boolean => {
  if (
    labels?.length !== CALENDAR_MONTH_COUNT ||
    !datasets ||
    datasets.length === 0
  ) {
    return false;
  }

  return datasets.every(
    (dataset) => dataset.data?.length === CALENDAR_MONTH_COUNT,
  );
};

const createIndexRange = (start: number, end: number): number[] =>
  Array.from({ length: end - start + 1 }, (_, offset) => start + offset);

const isPartialYtdSelection = (
  dtEnd: string,
  cutoffDate: string | undefined,
): boolean => {
  const normalizedCutoffDate = normalizeTimePeriodDtEnd(cutoffDate);

  return Boolean(
    normalizedCutoffDate &&
    getClosedYear(dtEnd) === getClosedYear(normalizedCutoffDate) &&
    dtEnd < normalizedCutoffDate,
  );
};

/**
 * Derives highlighted indexes for an annual line chart whose fixed positional
 * contract is January at index 0 through December at index 11.
 */
export const deriveTimePeriodHighlightedIndexes = ({
  periodType,
  dtEnd,
  cutoffDate,
  labels,
  datasets,
}: DeriveTimePeriodHighlightedIndexesParams): number[] => {
  const normalizedType = normalizeTimePeriodType(periodType);
  if (
    !normalizedType ||
    !isCanonicalMonthStartDate(dtEnd) ||
    !hasFixedCalendarYearShape(labels, datasets)
  ) {
    return [];
  }

  const endMonthIndex = getClosedMonthIndex(dtEnd);

  switch (normalizedType) {
    case TimePeriodType.MTH:
      return [endMonthIndex];
    case TimePeriodType.R3M:
      return createIndexRange(Math.max(0, endMonthIndex - 2), endMonthIndex);
    case TimePeriodType.QTR:
      return (endMonthIndex + 1) % 3 === 0
        ? createIndexRange(endMonthIndex - 2, endMonthIndex)
        : [];
    case TimePeriodType.HALF:
      return endMonthIndex === 5 || endMonthIndex === 11
        ? createIndexRange(endMonthIndex - 5, endMonthIndex)
        : [];
    case TimePeriodType.YTD:
      return isPartialYtdSelection(dtEnd, cutoffDate)
        ? createIndexRange(0, endMonthIndex)
        : [];
    case TimePeriodType.FY:
    default:
      return [];
  }
};
